(() => {
  const KEY = 'shiftmate-workspace-v1';
  const SHIFT_RULES = [
    { id: 'day', name: 'Day shift', time: '7:30 AM – 7:30 PM', start: '07:30', tone: 'day' },
    { id: 'night', name: 'Night shift', time: '7:30 PM – 7:30 AM', start: '19:30', tone: 'night' }
  ];
  const PALETTE = ['teal', 'blue', 'coral', 'gold'];
  const isPublicSignup = document.querySelector('[data-shiftmate-mode="signup"]') !== null;
  if (isPublicSignup) document.body.classList.add('public-signup');
  let remoteRevision = null;
  let sharedReady = false;
  let syncQueue = Promise.resolve();
  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
  const isoToday = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  const addDays = (value, amount) => { const d = new Date(`${value}T12:00:00`); d.setDate(d.getDate()+amount); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  const formatDate = (value, options = { weekday:'short', day:'numeric', month:'short' }) => new Intl.DateTimeFormat('en-MY', options).format(new Date(`${value}T12:00:00`));
  const fullDate = (value) => new Intl.DateTimeFormat('en-MY',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(`${value}T12:00:00`));
  const nowTime = () => new Intl.DateTimeFormat('en-MY',{hour:'numeric',minute:'2-digit'}).format(new Date());
  const escapeHtml = (s='') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const initials = (name='') => name.trim().split(/\s+/).slice(0,2).map(p=>p[0]||'').join('').toUpperCase();
  const defaultData = () => {
    const today = isoToday(), tomorrow = addDays(today,1), next = addDays(today,2);
    const agencies = [
      {id:'peak', name:'Peak Workforce', pic:'Aina Rahman', phone:'+60 12-345 0182', defaultQuota:12, tone:'teal', active:true},
      {id:'swift', name:'SwiftStaff Agency', pic:'Daniel Lee', phone:'+60 11-208 5571', defaultQuota:9, tone:'blue', active:true},
      {id:'nova', name:'Nova Crew Services', pic:'Farah Nordin', phone:'+60 17-660 3820', defaultQuota:7, tone:'coral', active:true}
    ];
    const warehouses = [
      {id:'shah-alam',name:'Shah Alam Fulfilment Hub',city:'Shah Alam, Selangor',code:'SAH-01',tone:'',active:true,shifts:['day','night']},
      {id:'sepang',name:'Sepang Sort Centre',city:'Sepang, Selangor',code:'SSC-04',tone:'teal-cover',active:true,shifts:['day','night']},
      {id:'klang',name:'Klang Crossdock',city:'Klang, Selangor',code:'KCD-02',tone:'coral-cover',active:true,shifts:['day']}
    ];
    const workers = [
      {id:'w1',name:'Aqil Hakim',workerId:'SH-2031',agencyId:'peak',phone:'012 551 0198',isNew:false,banned:false,joined:today},
      {id:'w2',name:'Melissa Tan',workerId:'SH-1984',agencyId:'swift',phone:'016 334 7854',isNew:false,banned:false,joined:today},
      {id:'w3',name:'Harith Iskandar',workerId:'SH-2068',agencyId:'nova',phone:'011 205 4991',isNew:false,banned:false,joined:today},
      {id:'w4',name:'Nadia Sofea',workerId:'SH-2110',agencyId:'peak',phone:'017 944 3008',isNew:false,banned:false,joined:tomorrow},
      {id:'w5',name:'Kevin Goh',workerId:'SH-1917',agencyId:'swift',phone:'012 770 6435',isNew:false,banned:true,banReason:'Repeated late cancellation without an approved reason',joined:today}
    ];
    const bookings = [
      {id:'BK-1042',workerRef:'w1',agencyId:'peak',warehouseId:'shah-alam',shiftId:'day',date:today,status:'confirmed',createdAt:Date.now()-1000*60*18,lateCancel:false},
      {id:'BK-1041',workerRef:'w2',agencyId:'swift',warehouseId:'shah-alam',shiftId:'day',date:today,status:'confirmed',createdAt:Date.now()-1000*60*49,lateCancel:false},
      {id:'BK-1040',workerRef:'w3',agencyId:'nova',warehouseId:'sepang',shiftId:'day',date:today,status:'confirmed',createdAt:Date.now()-1000*60*93,lateCancel:false},
      {id:'BK-1039',workerRef:'w4',agencyId:'peak',warehouseId:'sepang',shiftId:'night',date:today,status:'pending',createdAt:Date.now()-1000*60*150,lateCancel:false},
      {id:'BK-1038',workerRef:'w5',agencyId:'swift',warehouseId:'klang',shiftId:'day',date:tomorrow,status:'confirmed',createdAt:Date.now()-1000*60*200,lateCancel:false},
      {id:'BK-1037',workerRef:'w2',agencyId:'swift',warehouseId:'shah-alam',shiftId:'night',date:tomorrow,status:'confirmed',createdAt:Date.now()-1000*60*270,lateCancel:false},
      {id:'BK-1036',workerRef:'w1',agencyId:'peak',warehouseId:'sepang',shiftId:'day',date:next,status:'confirmed',createdAt:Date.now()-1000*60*340,lateCancel:false}
    ];
    return {agencies,warehouses,workers,bookings,quotas:{},settings:{cancelWindow:90,requireReason:true,whatsappAlerts:true},activity:[]};
  };
  let db;
  if (isPublicSignup) db = {agencies:[],warehouses:[],workers:[],bookings:[],quotas:{},settings:{cancelWindow:90,requireReason:true,whatsappAlerts:false},activity:[]};
  else {try { db = JSON.parse(localStorage.getItem(KEY)) || defaultData(); } catch { db = defaultData(); }}
  let view = isPublicSignup ? 'worker-portal' : 'overview';
  let selectedDate = isoToday();
  let selectedWarehouse = 'all';
  let bookingSearch = '';
  let workerSearch = '';
  let bookingFilter = 'all';
  let workerFilter = 'all';
  let bookingPage = 1;
  let workerPage = 1;
  const PAGE_SIZE = 8;
  const save = () => {
    if (isPublicSignup) return;
    const snapshot = JSON.stringify(db);
    localStorage.setItem(KEY, snapshot);
    if (!sharedReady) return;
    syncQueue = syncQueue.then(async () => {
      const response = await fetch('/api/state', {method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({revision:remoteRevision,state:JSON.parse(snapshot)})});
      if (response.status === 409) throw new Error('This workspace was changed in another session. Reload the latest shared data before continuing.');
      const result = await response.json();
      if (!response.ok) throw new Error(result.error || 'Shared workspace could not be saved.');
      remoteRevision = result.revision;
    }).catch(async error => {
      sharedReady = false;
      try { const latest = await fetch('/api/state',{cache:'no-store'}); if(latest.ok){const data=await latest.json();if(data?.state){db=data.state;remoteRevision=data.revision;localStorage.setItem(KEY,JSON.stringify(db));renderApp();}} } catch {}
      toast(error.message || 'Shared workspace could not be saved.','error');
    });
  };
  const agency = id => db.agencies.find(a=>a.id===id);
  const warehouse = id => db.warehouses.find(w=>w.id===id);
  const shift = id => SHIFT_RULES.find(s=>s.id===id);
  const worker = id => db.workers.find(w=>w.id===id);
  const booking = id => db.bookings.find(b=>b.id===id);
  const quotaKey = (date,warehouseId,shiftId,agencyId) => [date,warehouseId,shiftId,agencyId].join('|');
  const getQuota = (date,warehouseId,shiftId,agencyId) => Number(db.quotas[quotaKey(date,warehouseId,shiftId,agencyId)] ?? agency(agencyId)?.defaultQuota ?? 0);
  const activeBookings = (date,warehouseId,shiftId,agencyId) => db.bookings.filter(b=>b.date===date&&b.warehouseId===warehouseId&&b.shiftId===shiftId&&b.agencyId===agencyId&&['confirmed','pending'].includes(b.status)).length;
  const availableFor = (date,warehouseId,shiftId,agencyId) => Math.max(0,getQuota(date,warehouseId,shiftId,agencyId)-activeBookings(date,warehouseId,shiftId,agencyId));
  const allOpenings = (date,warehouseId,shiftId) => db.agencies.filter(a=>a.active).reduce((sum,a)=>sum+availableFor(date,warehouseId,shiftId,a.id),0);
  const countShift = (date,warehouseId,shiftId) => db.bookings.filter(b=>b.date===date&&(!warehouseId||b.warehouseId===warehouseId)&&b.shiftId===shiftId&&['confirmed','pending'].includes(b.status)).length;
  const totalCapacity = (date,warehouseId,shiftId) => db.agencies.filter(a=>a.active).reduce((n,a)=>n+getQuota(date,warehouseId||db.warehouses[0]?.id,shiftId,a.id),0);
  const capacityAcross = (date,shiftId) => db.warehouses.filter(w=>w.active).reduce((n,w)=>n+db.agencies.filter(a=>a.active).reduce((m,a)=>m+getQuota(date,w.id,shiftId,a.id),0),0);
  const logActivity = (message,type='booked') => { db.activity.unshift({message,type,time:Date.now()}); db.activity=db.activity.slice(0,12); };
  const makeBookingId = () => `BK-${Math.max(1000,...db.bookings.map(b=>Number((b.id||'').split('-')[1])||0))+1}`;
  const makeWorkerId = () => `SH-${Math.floor(1000+Math.random()*8999)}`;
  const labelStatus = status => status==='confirmed'?'Confirmed':status==='pending'?'Pending':status==='cancelled'?'Cancelled':'Completed';
  const statusClass = status => status==='confirmed'?'':status==='pending'?'pending':status==='cancelled'?'cancelled':'neutral';
  const datesOptions = (chosen=selectedDate) => [0,1,2,3,4,5,6,7].map(n=>{const d=addDays(isoToday(),n);return `<option value="${d}" ${d===chosen?'selected':''}>${n===0?'Today · ':''}${escapeHtml(formatDate(d))}</option>`;}).join('');
  const warehouseOptions = (chosen='') => db.warehouses.filter(w=>w.active).map(w=>`<option value="${w.id}" ${w.id===chosen?'selected':''}>${escapeHtml(w.name)}</option>`).join('');
  const agencyOptions = (chosen='', activeOnly=true) => db.agencies.filter(a=>!activeOnly||a.active).map(a=>`<option value="${a.id}" ${a.id===chosen?'selected':''}>${escapeHtml(a.name)}</option>`).join('');
  const shiftOptions = (chosen='') => SHIFT_RULES.map(s=>`<option value="${s.id}" ${s.id===chosen?'selected':''}>${s.name} · ${s.time}</option>`).join('');
  const pageHead = (eyebrow,title,desc,actions='') => `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;
  const metric = (label,value,foot,tone='') => `<div class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon ${tone}">${tone==='blue'?'◈':tone==='coral'?'↗':tone==='gold'?'◷':'✳'}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`;
  const safeAgencyColor = a => a?.tone || 'teal';
  const avatarTone = tone => tone==='coral'?'coral':tone==='teal'?'teal':tone==='gold'?'gold':'';
  const renderOverview = () => {
    const current = db.bookings.filter(b=>b.date===selectedDate&&['confirmed','pending'].includes(b.status));
    const confirmed=current.filter(b=>b.status==='confirmed').length;
    const pending=current.filter(b=>b.status==='pending').length;
    const cancelled=db.bookings.filter(b=>b.date===selectedDate&&b.status==='cancelled'&&b.lateCancel).length;
    const agenciesActive=db.agencies.filter(a=>a.active).length;
    const whFilter=selectedWarehouse==='all'?null:selectedWarehouse;
    const open=SHIFT_RULES.reduce((sum,s)=>sum+(whFilter?allOpenings(selectedDate,whFilter,s.id):db.warehouses.filter(w=>w.active).reduce((n,w)=>n+allOpenings(selectedDate,w.id,s.id),0)),0);
    const bookedTotal=whFilter?current.filter(b=>b.warehouseId===whFilter).length:current.length;
    const cap=whFilter?SHIFT_RULES.reduce((n,s)=>n+totalCapacity(selectedDate,whFilter,s.id),0):db.warehouses.filter(w=>w.active).reduce((n,w)=>n+SHIFT_RULES.reduce((m,s)=>m+totalCapacity(selectedDate,w.id,s.id),0),0);
    const warehouseFilter=`<select class="select-control" id="overviewWarehouse"><option value="all" ${selectedWarehouse==='all'?'selected':''}>All warehouses</option>${warehouseOptions(selectedWarehouse==='all'?'':selectedWarehouse)}</select>`;
    const actions=`${warehouseFilter}<select class="date-select" id="overviewDate">${datesOptions()}</select><button class="btn" data-action="worker-portal">Worker sign-up ↗</button><button class="btn btn-primary" data-action="new-booking">＋ New booking</button>`;
    const shiftRows=SHIFT_RULES.map((s,i)=>{
      const total=whFilter?countShift(selectedDate,whFilter,s.id):db.bookings.filter(b=>b.date===selectedDate&&b.shiftId===s.id&&['confirmed','pending'].includes(b.status)).length;
      const capacity=whFilter?totalCapacity(selectedDate,whFilter,s.id):db.warehouses.filter(w=>w.active).reduce((n,w)=>n+totalCapacity(selectedDate,w.id,s.id),0);
      const pct=capacity?Math.min(100,Math.round(total/capacity*100)):0;
      const openSeats=Math.max(0,capacity-total);
      return `<div class="shift-row"><span class="shift-color ${s.tone==='night'?'night':''}"></span><div class="shift-main"><b>${s.name}</b><small>${s.time} · ${whFilter?escapeHtml(warehouse(whFilter)?.city||''):'All active warehouses'}</small></div><div class="shift-progress"><div class="progress-top"><span>${total} booked</span><span>${capacity} quota</span></div><div class="progress-bar"><span class="${i===1?'blue':''}" style="width:${pct}%"></span></div></div><div class="shift-status">${openSeats} open spots</div></div>`;
    }).join('');
    const agencies=db.agencies.filter(a=>a.active).map(a=>{
      const count=current.filter(b=>b.agencyId===a.id&&(!whFilter||b.warehouseId===whFilter)).length;
      const quota=whFilter?SHIFT_RULES.reduce((n,s)=>n+getQuota(selectedDate,whFilter,s.id,a.id),0):db.warehouses.filter(w=>w.active).reduce((m,w)=>m+SHIFT_RULES.reduce((n,s)=>n+getQuota(selectedDate,w.id,s.id,a.id),0),0);
      return `<div class="coverage-line"><span class="agency-dot" style="background:${a.tone==='blue'?'#7182f1':a.tone==='coral'?'#fa987b':a.tone==='gold'?'#ddb248':'#3ebda8'}"></span><div class="agency-line-main"><b>${escapeHtml(a.name)}</b><small>${escapeHtml(a.pic)} · PIC</small></div><span class="agency-line-count">${count} / ${quota}</span></div>`;
    }).join('')||'<div class="empty-inset">Add an agency to start tracking coverage.</div>';
    const activity=(db.activity.length?db.activity:[
      {message:'Aqil Hakim confirmed for Shah Alam · Day shift',type:'booked',time:Date.now()-1000*60*18},
      {message:'Peak Workforce updated their day-shift quota',type:'quota',time:Date.now()-1000*60*54},
      {message:'A late cancellation needs PIC review',type:'cancel',time:Date.now()-1000*60*88}
    ]).slice(0,4).map(a=>`<div class="activity-item"><span class="activity-icon ${a.type==='cancel'?'coral':a.type==='quota'?'blue':''}">${a.type==='cancel'?'!':a.type==='quota'?'↗':'✓'}</span><div class="activity-text">${escapeHtml(a.message)}<small>${relativeTime(a.time)}</small></div></div>`).join('');
    return `${pageHead('SHIFT OPERATIONS',`Good ${new Date().getHours()<12?'morning':'afternoon'}, Nur`,`${fullDate(selectedDate)} · Keep every shift covered with one clear view.`,actions)}
      <div class="welcome-banner"><div class="welcome-copy"><div class="eyebrow">YOUR DAILY SNAPSHOT</div><h2>Every shift, in sync.</h2><p>Track bookings, agency coverage and last-minute changes in one place.</p></div><div class="welcome-art" aria-hidden="true"><div class="art-box"></div><div class="art-conveyor"></div><div class="art-person"></div></div></div>
      <div class="metric-grid">${metric('Confirmed workers',confirmed,`<strong>${pending} pending</strong> for ${escapeHtml(formatDate(selectedDate,{day:'numeric',month:'short'}))}`)}${metric('Open shift spots',open,`${bookedTotal} of ${cap} quota filled`,'blue')}${metric('Active agencies',agenciesActive,'Across your warehouse network','coral')}${metric('Late cancellations',cancelled,cancelled?'<strong>Needs PIC review</strong>':'No reviews needed','gold')}</div>
      <div class="content-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Today’s shift plan</div><div class="panel-subtitle">Live bookings and agency capacity</div></div><button class="text-link" data-nav="bookings">View all bookings ↗</button></div><div class="shift-list">${shiftRows}</div></section><div class="right-stack"><section class="panel coverage-panel"><div class="panel-head"><div><div class="panel-title">Agency coverage</div><div class="panel-subtitle">Booked workers against agency quota</div></div><button class="text-link" data-nav="agencies">Manage</button></div><div class="coverage-body">${agencies}</div><div class="coverage-foot">Quota figures are visible to coordinators only. Workers see availability without agency limits.</div></section><section class="panel activity-panel"><div class="panel-head"><div><div class="panel-title">Recent activity</div><div class="panel-subtitle">Changes across your workspace</div></div><button class="text-link" data-nav="updates">Updates</button></div><div class="activity-list">${activity}</div></section></div></div>`;
  };
  function relativeTime(timestamp){const mins=Math.max(0,Math.round((Date.now()-Number(timestamp))/60000));if(mins<1)return'just now';if(mins<60)return`${mins} min ago`;const hr=Math.floor(mins/60);if(hr<24)return`${hr} hr${hr===1?'':'s'} ago`;return`${Math.floor(hr/24)} day ago`;}
  const bookingRow = b => {
    const w=worker(b.workerRef),a=agency(b.agencyId),wh=warehouse(b.warehouseId),s=shift(b.shiftId);
    return `<tr><td><div class="person-cell"><span class="mini-avatar ${avatarTone(a?.tone)}">${initials(w?.name||'?')}</span><span><b>${escapeHtml(w?.name||'Unknown worker')}</b><small>${escapeHtml(w?.workerId||'New worker')}</small></span></div></td><td>${escapeHtml(a?.name||'—')}</td><td>${escapeHtml(wh?.name||'—')}</td><td><b>${escapeHtml(s?.name||'—')}</b><small style="display:block;color:#9aa3b1;margin-top:3px">${escapeHtml(s?.time||'')}</small></td><td>${escapeHtml(formatDate(b.date,{day:'numeric',month:'short'}))}</td><td><span class="status-pill ${statusClass(b.status)}">${labelStatus(b.status)}${b.lateCancel?' · review':''}</span></td><td><div class="table-actions"><button class="tiny-action" title="View booking" aria-label="View booking" data-action="view-booking" data-id="${b.id}">↗</button>${b.status==='pending'?`<button class="tiny-action" title="Confirm booking" aria-label="Confirm booking" data-action="confirm-booking" data-id="${b.id}">✓</button>`:''}${b.status!=='cancelled'?`<button class="tiny-action" title="Cancel booking" aria-label="Cancel booking" data-action="cancel-booking" data-id="${b.id}">×</button>`:''}</div></td></tr>`;
  };
  const pagination = (total,page,which) => {const pages=Math.max(1,Math.ceil(total/PAGE_SIZE));if(total<=PAGE_SIZE)return'';return `<div class="pagination"><span>Showing ${(page-1)*PAGE_SIZE+1}–${Math.min(total,page*PAGE_SIZE)} of ${total}</span><div><button class="tiny-action" data-action="page-${which}" data-page="${Math.max(1,page-1)}" ${page<=1?'disabled':''}>‹</button><span class="pagination-number">${page} / ${pages}</span><button class="tiny-action" data-action="page-${which}" data-page="${Math.min(pages,page+1)}" ${page>=pages?'disabled':''}>›</button></div></div>`;};
  const renderBookings = () => {
    const actions=`<button class="btn" data-action="export-bookings">⇩ Export CSV</button><button class="btn btn-primary" data-action="new-booking">＋ New booking</button>`;
    const rows=db.bookings.filter(b=>bookingFilter==='all'||b.status===bookingFilter).filter(b=>{const q=bookingSearch.toLowerCase();if(!q)return true;const w=worker(b.workerRef),a=agency(b.agencyId),wh=warehouse(b.warehouseId);return [w?.name,w?.workerId,a?.name,wh?.name,b.id].some(v=>String(v||'').toLowerCase().includes(q));}).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt-a.createdAt);
    const pageRows=rows.slice((bookingPage-1)*PAGE_SIZE,bookingPage*PAGE_SIZE);
    return `${pageHead('WORKFORCE SCHEDULING','Shift bookings','Review worker requests, manage confirmations and handle cancellations.',actions)}<section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">All bookings <span class="muted">(${rows.length})</span></div><div class="panel-subtitle">Worker bookings across every warehouse</div></div><div class="segmented"><button data-book-filter="all" class="${bookingFilter==='all'?'active':''}">All</button><button data-book-filter="confirmed" class="${bookingFilter==='confirmed'?'active':''}">Confirmed</button><button data-book-filter="pending" class="${bookingFilter==='pending'?'active':''}">Pending</button><button data-book-filter="cancelled" class="${bookingFilter==='cancelled'?'active':''}">Cancelled</button></div></div><div class="table-toolbar"><label class="searchbox"><span class="search-icon">⌕</span><input id="bookingSearch" placeholder="Search worker, agency or booking ID" value="${escapeHtml(bookingSearch)}" /></label><div class="toolbar-filters"><select class="select-control" id="bookingDateFilter"><option value="all">All dates</option>${[0,1,2,3,4,5,6,7].map(n=>{const d=addDays(isoToday(),n);return `<option value="${d}">${n===0?'Today · ':''}${escapeHtml(formatDate(d))}</option>`}).join('')}</select><select class="select-control" id="bookingWarehouseFilter"><option value="all">All warehouses</option>${warehouseOptions()}</select></div></div><div class="table-wrap"><table><thead><tr><th>Worker</th><th>Agency</th><th>Warehouse</th><th>Shift</th><th>Date</th><th>Status</th><th>Actions</th></tr></thead><tbody id="bookingTableBody">${pageRows.length?pageRows.map(bookingRow).join(''):`<tr><td colspan="7"><div class="empty-state"><b>No bookings found</b>Try changing your search or filters.</div></td></tr>`}</tbody></table></div>${pagination(rows.length,bookingPage,'bookings')}</section>`;
  };
  const renderWorkers = () => {
    const actions=`<button class="btn" data-action="export-workers">⇩ Export workers</button><button class="btn btn-primary" data-action="new-worker">＋ Add worker</button>`;
    const rows=db.workers.filter(w=>workerFilter==='all'||(workerFilter==='active'?!w.banned:w.banned)).filter(w=>{const q=workerSearch.toLowerCase();return !q||[w.name,w.workerId,agency(w.agencyId)?.name].some(v=>String(v||'').toLowerCase().includes(q));}).sort((a,b)=>a.name.localeCompare(b.name));
    const pageRows=rows.slice((workerPage-1)*PAGE_SIZE,workerPage*PAGE_SIZE);
    const body=pageRows.map(w=>{const a=agency(w.agencyId),count=db.bookings.filter(b=>b.workerRef===w.id&&['confirmed','pending'].includes(b.status)).length,last=db.bookings.filter(b=>b.workerRef===w.id).sort((a,b)=>b.date.localeCompare(a.date))[0];return `<tr><td><div class="person-cell"><span class="mini-avatar ${avatarTone(a?.tone)}">${initials(w.name)}</span><span><b>${escapeHtml(w.name)}</b><small>${escapeHtml(w.workerId)}${w.isNew?' · New worker':''}</small></span></div></td><td>${escapeHtml(a?.name||'—')}</td><td>${escapeHtml(w.phone||'—')}</td><td>${count} upcoming</td><td>${last?escapeHtml(formatDate(last.date,{day:'numeric',month:'short'})):'—'}</td><td><span class="status-pill ${w.banned?'banned':''}">${w.banned?'Blocked':'Active'}</span></td><td><div class="table-actions"><button class="tiny-action" title="View worker" aria-label="View worker" data-action="view-worker" data-id="${w.id}">↗</button><button class="tiny-action" title="${w.banned?'Unblock':'Block'} worker" aria-label="${w.banned?'Unblock':'Block'} worker" data-action="toggle-ban" data-id="${w.id}">${w.banned?'✓':'⊘'}</button></div></td></tr>`;}).join('');
    return `${pageHead('PEOPLE DIRECTORY','Workers','Manage worker records, booking history and agency access.',actions)}<div class="metric-grid">${metric('Total workers',db.workers.length,'Registered across all agencies')}${metric('Active workers',db.workers.filter(w=>!w.banned).length,'Can request warehouse shifts','blue')}${metric('Blocked workers',db.workers.filter(w=>w.banned).length,'Managed by agency PICs','coral')}${metric('Late cancel reviews',db.bookings.filter(b=>b.lateCancel&&b.status==='cancelled').length,'Review before applying a block','gold')}</div><section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">Worker directory</div><div class="panel-subtitle">Worker IDs, agency assignments and booking activity</div></div><div class="segmented"><button data-worker-filter="all" class="${workerFilter==='all'?'active':''}">All</button><button data-worker-filter="active" class="${workerFilter==='active'?'active':''}">Active</button><button data-worker-filter="blocked" class="${workerFilter==='blocked'?'active':''}">Blocked</button></div></div><div class="table-toolbar"><label class="searchbox"><span class="search-icon">⌕</span><input id="workerSearch" placeholder="Search name or worker ID" value="${escapeHtml(workerSearch)}" /></label><div class="toolbar-filters"><span class="caps-note">Only agency PICs can change worker access.</span></div></div><div class="table-wrap"><table><thead><tr><th>Worker</th><th>Agency</th><th>Phone</th><th>Bookings</th><th>Last shift</th><th>Access</th><th>Actions</th></tr></thead><tbody>${body||`<tr><td colspan="7"><div class="empty-state"><b>No workers found</b>Try another name or filter.</div></td></tr>`}</tbody></table></div>${pagination(rows.length,workerPage,'workers')}</section>`;
  };
  const renderAgencies = () => {
    const cards=db.agencies.map(a=>{const activeWorkers=db.workers.filter(w=>w.agencyId===a.id&&!w.banned).length;const todayBookings=db.bookings.filter(b=>b.date===selectedDate&&b.agencyId===a.id&&['confirmed','pending'].includes(b.status)).length;const q=db.warehouses.filter(w=>w.active).reduce((n,w)=>n+SHIFT_RULES.reduce((m,s)=>m+getQuota(selectedDate,w.id,s.id,a.id),0),0);return `<article class="agency-card"><div class="agency-card-top"><span class="agency-avatar ${a.tone}">${initials(a.name)}</span><span class="status-pill ${a.active?'':'neutral'}">${a.active?'Active':'Paused'}</span></div><h3>${escapeHtml(a.name)}</h3><p>Agency ID · ${escapeHtml(a.id.toUpperCase())}</p><div class="agency-stats"><div><b>${activeWorkers}</b><small>active workers</small></div><div><b>${todayBookings} / ${q}</b><small>booked · quota today</small></div></div><div class="agency-card-foot"><span class="agency-pic"><span class="mini-avatar ${avatarTone(a.tone)}">${initials(a.pic)}</span>${escapeHtml(a.pic)} · PIC</span><button class="btn btn-small" data-action="edit-quota" data-id="${a.id}">Set quota</button></div><div class="agency-card-actions"><button class="text-link" data-action="agency-message" data-id="${a.id}">Copy WhatsApp update</button><button class="text-link" data-action="toggle-agency" data-id="${a.id}">${a.active?'Pause':'Activate'}</button></div></article>`;}).join('');
    return `${pageHead('AGENCY PARTNERS','Agencies','Set agency quotas and see how each partner is filling shifts.',`<select class="date-select" id="agencyDate">${datesOptions()}</select><button class="btn btn-primary" data-action="new-agency">＋ Add agency</button>`)}<div class="agency-grid">${cards||'<div class="empty-state">No agencies yet.</div>'}</div><p class="demo-note">Agency quota counts are only shown to workspace coordinators. Worker sign-up displays availability by status only.</p>`;
  };
  const renderWarehouses = () => {
    const cards=db.warehouses.map(w=>{const todayCount=db.bookings.filter(b=>b.date===selectedDate&&b.warehouseId===w.id&&['confirmed','pending'].includes(b.status)).length;const spots=SHIFT_RULES.filter(s=>w.shifts.includes(s.id)).reduce((n,s)=>n+allOpenings(selectedDate,w.id,s.id),0);return `<article class="warehouse-card"><div class="warehouse-cover ${w.tone}"><span class="warehouse-building"></span><span class="warehouse-pin">⌖</span></div><div class="warehouse-info"><div class="eyebrow">${escapeHtml(w.code)} · ${w.active?'ACTIVE':'PAUSED'}</div><h3>${escapeHtml(w.name)}</h3><p>${escapeHtml(w.city)}</p><div class="warehouse-pills">${w.shifts.map(id=>`<span>${escapeHtml(shift(id)?.name||id)}</span>`).join('')}</div><div class="warehouse-bottom"><span>${todayCount} workers today</span><b>${spots} open spots</b></div></div></article>`;});
    return `${pageHead('SITE DIRECTORY','Warehouses','View active work sites and coordinate staffing coverage.',`<select class="date-select" id="warehouseDate">${datesOptions()}</select><button class="btn btn-primary" data-action="new-warehouse">＋ Add warehouse</button>`)}<div class="warehouse-grid">${cards.join('')||'<div class="empty-state">No warehouse locations yet.</div>'}</div>`;
  };
  const getAvailabilityMarkup = (date,warehouseId,shiftId,agencyId='') => db.agencies.filter(a=>a.active).map(a=>{const open=availableFor(date,warehouseId,shiftId,a.id)>0;return `<div class="availability-item"><span><b>${escapeHtml(a.name)}</b><small>${open?'Applications open for this agency':'Agency quota has been reached'}</small></span><span class="${open?'open-indicator':'full-indicator'}">${open?'Open':'Full'}</span></div>`;}).join('')||'<div class="empty-inset">No agencies are accepting bookings at the moment.</div>';
  const renderPortal = () => {
    const firstWh=db.warehouses.find(w=>w.active),firstAgency=db.agencies.find(a=>a.active);
    const firstShift=SHIFT_RULES[0];
    return `<div class="portal-wrap"><div class="page-head"><div><div class="eyebrow">WORKER SIGN-UP</div><h1>Find your next shift</h1><p>Choose a work site and shift, then send your request to the agency PIC.</p></div>${isPublicSignup?'':'<div class="head-actions"><button class="btn" data-action="admin-view">← Back to workspace</button></div>'}</div><div class="portal-banner"><div><h2>Good work starts with a clear plan.</h2><p>One quick request. Your agency will confirm the details.</p></div><div class="portal-icon">✳</div></div><div class="content-grid"><form class="panel portal-card" id="workerSignupForm"><h3>Your details</h3><p class="section-note">Use the same name and ID that your agency has on file.</p><div class="form-grid"><div class="field hidden" aria-hidden="true"><label>Website</label><input name="website" tabindex="-1" autocomplete="off"></div><div class="field full"><label>Are you a new or returning worker?</label><div class="choice-row"><label class="choice-card selected" data-choice-card><input type="radio" name="workerType" value="existing" checked><b>Returning worker</b><small>I already have a warehouse worker ID</small></label><label class="choice-card" data-choice-card><input type="radio" name="workerType" value="new"><b>New worker</b><small>I’m signing up for the first time</small></label></div></div><div class="field"><label for="signupName">Full name</label><input id="signupName" name="name" required minlength="2" maxlength="70" placeholder="e.g. Nur Aisyah" autocomplete="name"></div><div class="field" id="workerIdField"><label for="signupWorkerId">Warehouse worker ID</label><input id="signupWorkerId" name="workerId" required maxlength="24" placeholder="e.g. SH-2048"><span class="caps-note">Ask your agency PIC if you’re unsure.</span></div><div class="field"><label for="signupPhone">Phone number</label><input id="signupPhone" name="phone" required type="tel" minlength="8" maxlength="20" placeholder="e.g. 012 345 6789" autocomplete="tel"></div><div class="field"><label for="signupAgency">Agency</label><select id="signupAgency" name="agencyId" required>${agencyOptions(firstAgency?.id||'')}</select></div><div class="field"><label for="signupWarehouse">Warehouse</label><select id="signupWarehouse" name="warehouseId" required>${warehouseOptions(firstWh?.id||'')}</select></div><div class="field"><label for="signupShift">Working time</label><select id="signupShift" name="shiftId" required>${shiftOptions(firstShift.id)}</select></div><div class="field"><label for="signupDate">Shift date</label><select id="signupDate" name="date" required>${datesOptions()}</select></div><div class="field full"><div class="policy-note"><span class="policy-icon">ⓘ</span><span><strong>Cancellation policy:</strong> cancel at least ${db.settings.cancelWindow} minutes before your shift. Within that window, the agency PIC must review your reason. Repeated unapproved cancellations may block future sign-ups.</span></div></div></div><div class="form-footer"><span class="privacy-note">Your worker ID, phone and booking are saved in Shiftmate shared storage and visible to workspace admins and your agency PIC.</span><button class="btn btn-primary" type="submit">Request this shift <span>↗</span></button></div><p class="demo-note">Requests are sent to the Shiftmate workspace. Your agency PIC confirms the booking.</p></form><section class="panel availability-card"><div class="panel-head"><div><div class="panel-title">Agency availability</div><div class="panel-subtitle">Availability updates when you change shift details</div></div></div><div class="availability-list" id="signupAvailability">${getAvailabilityMarkup(isoToday(),firstWh?.id||'',firstShift.id)}</div><div class="coverage-foot">A full agency quota is hidden from workers. Try another agency, warehouse or shift.</div></section></div></div>`;
  };
  const renderUpdates = () => {
    const firstWh=db.warehouses.find(w=>w.active),firstShift=SHIFT_RULES[0];
    return `${pageHead('TEAM COMMUNICATION','WhatsApp updates','Create a clean availability message for agency PICs to share in their worker group.',`<select class="date-select" id="updateDate">${datesOptions()}</select>`)}<div class="content-grid"><section class="panel whatsapp-card"><div class="panel-title">Build a shift update</div><div class="panel-subtitle">Choose a site and shift to preview worker availability.</div><div class="quota-editor" style="grid-template-columns:1.2fr 1.2fr 1fr auto;margin-top:17px;padding:0"><div class="field"><label>Warehouse</label><select class="select-control" id="updateWarehouse">${warehouseOptions(firstWh?.id||'')}</select></div><div class="field"><label>Working time</label><select class="select-control" id="updateShift">${shiftOptions(firstShift.id)}</select></div><div class="field"><label>Agency</label><select class="select-control" id="updateAgency">${agencyOptions(db.agencies.find(a=>a.active)?.id||'')}</select></div><button class="btn" data-action="refresh-update">Refresh</button></div><div id="whatsappMessage">${whatsappPreview(selectedDate,firstWh?.id||'',firstShift.id,db.agencies.find(a=>a.active)?.id||'')}</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">How the update works</div><div class="panel-subtitle">Share clear availability without exposing quotas.</div></div></div><div class="quick-guide" style="padding:2px 19px 20px"><div class="guide-step"><span class="guide-num">1</span><div><b>Set the agency quota</b><p>Go to Agencies and set how many workers each partner can send for a shift.</p></div></div><div class="guide-step"><span class="guide-num">2</span><div><b>Copy the message</b><p>Shiftmate shows open or full status, the date and shift times.</p></div></div><div class="guide-step"><span class="guide-num">3</span><div><b>Paste it in WhatsApp</b><p>The agency PIC shares it with their temporary workers when ready.</p></div></div></div></section></div>`;
  };
  function whatsappPreview(date,warehouseId,shiftId,agencyId){const wh=warehouse(warehouseId),s=shift(shiftId),a=agency(agencyId);const open=availableFor(date,warehouseId,shiftId,agencyId)>0;const message=`SHIFT AVAILABILITY · ${wh?.name||'Warehouse'}\n${formatDate(date,{weekday:'long',day:'numeric',month:'long'})} · ${s?.name||'Shift'} (${s?.time||''})\nAgency: ${a?.name||'Agency'}\nStatus: ${open?'OPEN FOR SIGN-UP':'FULL — no further requests'}\n\nRegister through Shiftmate: ${location.origin}/signup\nWait for your agency PIC to confirm.`;return `<div class="whatsapp-preview"><small>MESSAGE PREVIEW · ${escapeHtml(a?.name||'AGENCY PIC')}</small><p>${escapeHtml(message)}</p></div><div style="margin-top:13px;display:flex;gap:8px"><button class="btn btn-teal" data-action="copy-whatsapp" data-message="${encodeURIComponent(message)}">▣ Copy for WhatsApp</button><button class="btn" data-nav="agencies">Manage quotas</button></div>`;}
  const renderSchedule = () => {const slots=db.warehouses.filter(w=>w.active).flatMap(w=>w.shifts.map(sid=>{const s=shift(sid),rows=db.bookings.filter(b=>b.date===selectedDate&&b.warehouseId===w.id&&b.shiftId===sid&&['confirmed','pending','completed'].includes(b.status));const quota=db.agencies.filter(a=>a.active).reduce((n,a)=>n+getQuota(selectedDate,w.id,sid,a.id),0);return `<article class="panel" style="padding:17px;margin-bottom:12px"><div class="panel-head"><div><div class="panel-title">${escapeHtml(w.name)} · ${escapeHtml(s?.name||sid)}</div><div class="panel-subtitle">${escapeHtml(w.city)} · ${escapeHtml(s?.time||'')}</div></div><span class="status-pill">${rows.length} / ${quota} booked</span></div><div class="shift-progress" style="width:100%;margin:12px 0"><div class="progress-bar"><span style="width:${quota?Math.min(100,Math.round(rows.length/quota*100)):0}%"></span></div></div><div class="panel-subtitle">${rows.length?rows.map(b=>`${escapeHtml(worker(b.workerRef)?.name||'Unknown')} · ${escapeHtml(agency(b.agencyId)?.name||'')} · ${labelStatus(b.status)}`).join('　•　'):'No workers booked for this shift yet.'}</div><div style="display:flex;gap:8px;margin-top:14px"><button class="btn btn-small" data-nav="bookings">View bookings</button><button class="btn btn-small" data-nav="agencies">Set agency quotas</button><button class="btn btn-small btn-primary" data-action="new-booking">＋ Add worker</button></div></article>`;})).join('');return `${pageHead('WORKFORCE SCHEDULING','Shift plan','View staffing capacity by warehouse, date and shift.',`<select class="date-select" id="scheduleDate">${datesOptions(selectedDate)}</select><button class="btn btn-primary" data-action="new-booking">＋ Add booking</button>`)}${slots||'<div class="empty-state">Add an active warehouse to create a shift plan.</div>'}`;};
  const renderAttendance = () => {const rows=db.bookings.filter(b=>b.date===selectedDate&&['confirmed','completed'].includes(b.status)).sort((a,b)=>a.shiftId.localeCompare(b.shiftId)||a.createdAt-b.createdAt);const list=rows.map(b=>`<tr><td><b>${escapeHtml(worker(b.workerRef)?.name||'Unknown')}</b><small style="display:block;color:#929bab;margin-top:3px">${escapeHtml(worker(b.workerRef)?.workerId||'')}</small></td><td>${escapeHtml(warehouse(b.warehouseId)?.name||'—')}</td><td>${escapeHtml(shift(b.shiftId)?.name||'—')}</td><td>${escapeHtml(agency(b.agencyId)?.name||'—')}</td><td><span class="status-pill ${b.attendance==='present'?'':'neutral'}">${b.attendance==='present'?'Present':b.attendance==='no-show'?'No-show':'Not marked'}</span></td><td><div class="table-actions"><button class="btn btn-small btn-teal" data-action="attendance-status" data-id="${b.id}" data-status="present">Present</button><button class="btn btn-small" data-action="attendance-status" data-id="${b.id}" data-status="no-show">No-show</button></div></td></tr>`).join('');return `${pageHead('SHIFT OPERATIONS','Attendance','Record who arrived and flag no-shows for the agency PIC.',`<select class="date-select" id="attendanceDate">${datesOptions(selectedDate)}</select><button class="btn" data-action="export-attendance">⇩ Export attendance</button>`)}<div class="metric-grid">${metric('Confirmed workers',rows.length,'For the selected work date')}${metric('Present',rows.filter(b=>b.attendance==='present').length,'Marked as arrived','blue')}${metric('No-shows',rows.filter(b=>b.attendance==='no-show').length,'Notify the agency PIC','coral')}${metric('Not marked',rows.filter(b=>!b.attendance||b.attendance==='unmarked').length,'Still needs an attendance decision','gold')}</div><section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">Attendance register</div><div class="panel-subtitle">${escapeHtml(fullDate(selectedDate))} · Confirmed bookings only</div></div></div><div class="table-wrap"><table><thead><tr><th>Worker</th><th>Warehouse</th><th>Shift</th><th>Agency</th><th>Attendance</th><th>Mark</th></tr></thead><tbody>${list||'<tr><td colspan="6"><div class="empty-state"><b>No confirmed workers</b>Approve shift requests before recording attendance.</div></td></tr>'}</tbody></table></div></section>`;};
  const pendingReviews = () => db.bookings.filter(b=>b.status==='cancelled'&&b.lateCancel&&!['approved','rejected'].includes(b.reviewStatus));
  const renderReviews = () => {const rows=pendingReviews().map(b=>`<tr><td><b>${escapeHtml(worker(b.workerRef)?.name||'Unknown')}</b><small style="display:block;color:#929bab;margin-top:3px">${escapeHtml(worker(b.workerRef)?.workerId||'')}</small></td><td>${escapeHtml(agency(b.agencyId)?.name||'—')}</td><td>${escapeHtml(warehouse(b.warehouseId)?.name||'—')}</td><td>${escapeHtml(shift(b.shiftId)?.name||'—')} · ${escapeHtml(formatDate(b.date))}</td><td>${escapeHtml(b.cancelReason||'No reason supplied')}</td><td><div class="table-actions"><button class="btn btn-small btn-teal" data-action="review-approve" data-id="${b.id}">Accept reason</button><button class="btn btn-small btn-danger" data-action="review-reject" data-id="${b.id}">Reject & block</button></div></td></tr>`).join('');return `${pageHead('AGENCY PIC WORKFLOW','Cancellation reviews','Review late cancellation reasons. Rejected reasons block future bookings until an agency PIC unblocks the worker.',`<button class="btn" data-nav="workers">Worker directory</button>`)}<section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">Waiting for PIC decision <span class="muted">(${pendingReviews().length})</span></div><div class="panel-subtitle">The released slot remains available; decisions are recorded in the worker history.</div></div></div><div class="table-wrap"><table><thead><tr><th>Worker</th><th>Agency</th><th>Warehouse</th><th>Shift</th><th>Reason</th><th>Decision</th></tr></thead><tbody>${rows||'<tr><td colspan="6"><div class="empty-state"><b>No cancellation reviews pending</b>New late cancellations will appear here.</div></td></tr>'}</tbody></table></div></section>`;};
  const renderReports = () => {const day=db.bookings.filter(b=>b.date===selectedDate),confirmed=day.filter(b=>['confirmed','completed'].includes(b.status)),present=confirmed.filter(b=>b.attendance==='present').length,missed=confirmed.filter(b=>b.attendance==='no-show').length,coverage=confirmed.length?Math.round(confirmed.length/Math.max(1,day.length)*100):0;const byAgency=db.agencies.map(a=>{const list=day.filter(b=>b.agencyId===a.id);return `<div class="coverage-line"><span class="agency-dot" style="background:${a.tone==='blue'?'#7182f1':a.tone==='coral'?'#fa987b':'#3ebda8'}"></span><div class="agency-line-main"><b>${escapeHtml(a.name)}</b><small>${list.filter(b=>b.status==='cancelled').length} cancellations · ${list.filter(b=>b.attendance==='no-show').length} no-shows</small></div><span class="agency-line-count">${list.filter(b=>['confirmed','completed'].includes(b.status)).length} confirmed</span></div>`;}).join('');return `${pageHead('WORKFORCE ANALYTICS','Reports','Review bookings, attendance and agency coverage for one shift date.',`<select class="date-select" id="reportDate">${datesOptions(selectedDate)}</select><button class="btn btn-primary" data-action="export-report">⇩ Export report CSV</button>`)}<div class="metric-grid">${metric('Shift requests',day.length,'All statuses for the selected date')}${metric('Confirmed',confirmed.length,`${coverage}% of requests confirmed`,'blue')}${metric('Present',present,'Attendance recorded','coral')}${metric('No-shows',missed,'Requires agency follow-up','gold')}</div><div class="content-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Agency performance</div><div class="panel-subtitle">Confirmed workers, cancellation and attendance</div></div></div><div class="coverage-body">${byAgency||'<div class="empty-inset">No agency records yet.</div>'}</div></section><section class="panel" style="padding:18px"><div class="panel-title">Shift coverage summary</div><div class="panel-subtitle">${escapeHtml(fullDate(selectedDate))}</div>${SHIFT_RULES.map(s=>{const n=confirmed.filter(b=>b.shiftId===s.id).length;return `<div class="setting-row"><div><b>${s.name}</b><p>${s.time}</p></div><b>${n} workers</b></div>`}).join('')}<button class="btn" data-nav="attendance">Open attendance register</button></section></div>`;};
  const renderSettings = () => `${pageHead('WORKSPACE CONTROL','Rules & settings','Set cancellation expectations and manage your local demo data.')}<div class="settings-layout"><section class="panel" style="padding:18px 20px"><div class="panel-title">Cancellation policy</div><div class="panel-subtitle">The same rule appears in the worker sign-up view.</div><div class="setting-row"><div><b>Late cancellation review window</b><p>Require a reason when a worker cancels close to the shift start.</p></div><div style="display:flex;align-items:center;gap:8px"><input id="cancelWindow" type="number" min="15" max="720" value="${db.settings.cancelWindow}" style="width:68px;height:35px;border:1px solid var(--line);border-radius:8px;padding:0 8px"><span class="muted" style="font-size:10px">minutes</span></div></div><div class="setting-row"><div><b>Agency PIC review</b><p>Late cancellations stay flagged until a PIC reviews the reason.</p></div><button class="toggle ${db.settings.requireReason?'on':''}" data-action="toggle-setting" data-setting="requireReason" aria-label="Toggle late cancellation reason"></button></div><div class="setting-row"><div><b>WhatsApp message helper</b><p>Copy shift availability updates for agency worker groups.</p></div><button class="toggle ${db.settings.whatsappAlerts?'on':''}" data-action="toggle-setting" data-setting="whatsappAlerts" aria-label="Toggle WhatsApp helper"></button></div><div class="setting-row"><div><b>Save policy</b><p>Changes apply to new cancellation requests and sign-up guidance.</p></div><button class="btn btn-small btn-primary" data-action="save-settings">Save changes</button></div></section><section class="panel" style="padding:18px 20px"><div class="panel-title">Demo data</div><div class="panel-subtitle">Your demo records are stored in this browser.</div><div class="setting-row"><div><b>Export workspace data</b><p>Download workers, agencies, shifts and bookings as JSON.</p></div><button class="btn btn-small" data-action="export-data">⇩ Export</button></div><div class="setting-row"><div><b>Reset sample data</b><p>Restore the original sample workers and shift bookings.</p></div><button class="btn btn-small btn-danger" data-action="reset-data">Reset</button></div><p class="demo-note" style="text-align:left;line-height:1.5">This prototype stores its data locally in this browser. A shared production workspace needs a hosted database and role-based accounts before worker groups use it.</p></section></div>`;
  const renderApp = () => {
    const content=$('#pageContent');
    content.innerHTML=view==='worker-portal'?renderPortal():({overview:renderOverview,bookings:renderBookings,workers:renderWorkers,agencies:renderAgencies,warehouses:renderWarehouses,schedule:renderSchedule,attendance:renderAttendance,reviews:renderReviews,reports:renderReports,updates:renderUpdates,settings:renderSettings}[view]||renderOverview)();
    const title=view==='worker-portal'?'Worker sign-up':view==='overview'?'Overview':view==='bookings'?'Shift bookings':view==='workers'?'Workers':view==='agencies'?'Agencies':view==='warehouses'?'Warehouses':view==='schedule'?'Shift plan':view==='attendance'?'Attendance':view==='reviews'?'Cancellation reviews':view==='reports'?'Reports':view==='updates'?'WhatsApp updates':'Rules & settings';
    $('#currentSection').textContent=title;
    $$('.nav-link').forEach(n=>n.classList.toggle('active',n.dataset.nav===view));
    $('#bookingNavCount').textContent=String(db.bookings.filter(b=>b.status==='pending').length||'');
    $('#reviewNavCount').textContent=String(pendingReviews().length||'');
    $('#todayLabel').textContent=new Intl.DateTimeFormat('en-MY',{weekday:'short',day:'numeric',month:'short'}).format(new Date());
  };
  const toast = (message,type='success') => {const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;$('#toastRegion').append(el);setTimeout(()=>el.remove(),3000);};
  const openModal = (title,subtitle,body,foot='') => {const root=$('#modalRoot');root.innerHTML=`<div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><div><h2 id="modalTitle">${title}</h2><p>${subtitle}</p></div><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</div>`;document.body.classList.add('no-scroll');};
  const closeModal = () => {$('#modalRoot').innerHTML='';document.body.classList.remove('no-scroll');};
  const makeBookingForm = (defaultBooking={}) => `<form id="adminBookingForm"><div class="form-grid"><div class="field full"><label for="adminWorker">Worker</label><select name="workerRef" id="adminWorker" required><option value="">Choose a worker</option>${db.workers.filter(w=>!w.banned).map(w=>`<option value="${w.id}" ${w.id===defaultBooking.workerRef?'selected':''}>${escapeHtml(w.name)} · ${escapeHtml(w.workerId)}</option>`).join('')}</select></div><div class="field"><label>Agency</label><select name="agencyId" required>${agencyOptions(defaultBooking.agencyId||db.agencies.find(a=>a.active)?.id||'')}</select></div><div class="field"><label>Warehouse</label><select name="warehouseId" required>${warehouseOptions(defaultBooking.warehouseId||db.warehouses.find(w=>w.active)?.id||'')}</select></div><div class="field"><label>Working time</label><select name="shiftId" required>${shiftOptions(defaultBooking.shiftId||'day')}</select></div><div class="field"><label>Shift date</label><input type="date" name="date" min="${isoToday()}" value="${defaultBooking.date||isoToday()}" required></div></div></form>`;
  const modalFoot = (cancel='Cancel',submit=null,action='submit-modal') => `${cancel?`<button class="btn" data-action="close-modal">${cancel}</button>`:''}${submit?`<button class="btn btn-primary" data-action="${action}">${submit}</button>`:''}`;
  const assertNoDuplicateShift = (workerRef,date,shiftId) => {const duplicate=db.bookings.find(b=>b.workerRef===workerRef&&b.date===date&&b.shiftId===shiftId&&['confirmed','pending','completed'].includes(b.status));if(duplicate)throw new Error(`This worker already has ${shift(shiftId)?.name||'a shift'} booked on ${formatDate(date)} (${duplicate.id}).`);};
  const addBooking = (values, status='confirmed') => {const w=worker(values.workerRef);if(!w)throw new Error('Select a worker first.');if(w.banned)throw new Error('This worker is blocked from new sign-ups.');if(w.agencyId!==values.agencyId)throw new Error('Choose the worker’s assigned agency.');assertNoDuplicateShift(w.id,values.date,values.shiftId);if(availableFor(values.date,values.warehouseId,values.shiftId,values.agencyId)<=0)throw new Error('This agency quota is full. Choose another agency or shift.');const b={id:makeBookingId(),workerRef:w.id,agencyId:values.agencyId,warehouseId:values.warehouseId,shiftId:values.shiftId,date:values.date,status,createdAt:Date.now(),lateCancel:false,attendance:'unmarked'};db.bookings.unshift(b);logActivity(`${w.name} booked for ${warehouse(values.warehouseId)?.name} · ${shift(values.shiftId)?.name}`,'booked');save();return b;};
  const openNewBooking = () => {openModal('Create a shift booking','Add a worker to an available warehouse shift.',makeBookingForm(),modalFoot('Cancel','Create booking','submit-admin-booking'));};
  const openNewWorker = () => {openModal('Add a worker','Create a worker record for an agency.',`<form id="newWorkerForm"><div class="form-grid"><div class="field full"><label>Full name</label><input name="name" required minlength="2" maxlength="70" placeholder="Worker’s full name"></div><div class="field"><label>Worker ID</label><input name="workerId" placeholder="e.g. SH-2084" maxlength="24"></div><div class="field"><label>Phone number</label><input name="phone" type="tel" placeholder="e.g. 012 345 6789"></div><div class="field full"><label>Agency</label><select name="agencyId" required>${agencyOptions(db.agencies.find(a=>a.active)?.id||'')}</select></div></div></form>`,modalFoot('Cancel','Add worker','submit-new-worker'));};
  const openNewAgency = () => {openModal('Add agency partner','Add an agency PIC and its default shift quota.',`<form id="newAgencyForm"><div class="form-grid"><div class="field full"><label>Agency name</label><input name="name" required maxlength="60" placeholder="e.g. BrightStaff Services"></div><div class="field"><label>Agency PIC</label><input name="pic" required maxlength="60" placeholder="Full name"></div><div class="field"><label>PIC phone</label><input name="phone" type="tel" maxlength="20" placeholder="Optional"></div><div class="field"><label>Default workers per shift</label><input name="defaultQuota" type="number" min="0" max="500" value="8" required></div><div class="field"><label>Label color</label><select name="tone"><option value="teal">Teal</option><option value="blue">Blue</option><option value="coral">Coral</option><option value="gold">Gold</option></select></div></div></form>`,modalFoot('Cancel','Add agency','submit-new-agency'));};
  const openNewWarehouse = () => {openModal('Add warehouse','Create a site that agencies can staff.',`<form id="newWarehouseForm"><div class="form-grid"><div class="field full"><label>Warehouse name</label><input name="name" required maxlength="70" placeholder="e.g. Petaling Jaya Delivery Hub"></div><div class="field"><label>City and state</label><input name="city" required maxlength="70" placeholder="e.g. Petaling Jaya, Selangor"></div><div class="field"><label>Warehouse code</label><input name="code" required maxlength="12" placeholder="PJH-03"></div><div class="field full"><label>Available shifts</label><div class="choice-row"><label class="choice-card selected" data-choice-card><input type="checkbox" name="shifts" value="day" checked><b>Day shift</b><small>7:30 AM – 7:30 PM</small></label><label class="choice-card selected" data-choice-card><input type="checkbox" name="shifts" value="night" checked><b>Night shift</b><small>7:30 PM – 7:30 AM</small></label></div></div></div></form>`,modalFoot('Cancel','Add warehouse','submit-new-warehouse'));};
  const openQuotaModal = (agencyId) => {const a=agency(agencyId);const wh=db.warehouses.find(w=>w.active);openModal(`Set ${escapeHtml(a?.name||'agency')} quota`,'Set the worker limit for each active shift. Workers only see Open or Full.',`<form id="quotaForm" data-agency="${agencyId}"><div class="form-grid"><div class="field"><label>Shift date</label><input type="date" name="date" min="${isoToday()}" value="${selectedDate}"></div><div class="field"><label>Warehouse</label><select name="warehouseId">${warehouseOptions(wh?.id||'')}</select></div><div class="field full"><label>Day shift quota</label><input type="number" name="day" min="0" max="500" value="${getQuota(selectedDate,wh?.id||'', 'day',agencyId)}"></div><div class="field full"><label>Night shift quota</label><input type="number" name="night" min="0" max="500" value="${getQuota(selectedDate,wh?.id||'', 'night',agencyId)}"></div></div><p class="demo-note" style="text-align:left">A new quota cannot be set below the number of confirmed and pending bookings.</p></form>`,modalFoot('Cancel','Save quotas','submit-quota'));};
  const openWorkerDetail = (workerId) => {const w=worker(workerId),a=agency(w?.agencyId);const history=db.bookings.filter(b=>b.workerRef===workerId).sort((x,y)=>y.date.localeCompare(x.date));const late=history.filter(b=>b.lateCancel);const auditRows=(w?.banHistory||[]).slice().reverse().slice(0,5).map(entry=>`<div class="activity-item"><span class="activity-icon ${entry.action==='blocked'?'coral':''}">${entry.action==='blocked'?'⊘':'✓'}</span><div class="activity-text">${escapeHtml(entry.action==='blocked'?'Access blocked':'Access restored')}<small>${escapeHtml(entry.reason||'')} · ${entry.time?relativeTime(entry.time):''} · ${escapeHtml(entry.by||'PIC')}</small></div></div>`).join('');const ban=w?.banned?`<div class="ban-banner"><span>!</span><span><b>Worker is currently blocked</b><br>${escapeHtml(w.banReason||'No reason recorded')}</span></div>`:'';const historyRows=history.length?history.slice(0,5).map(b=>`<div class="activity-item"><span class="activity-icon ${b.status==='cancelled'?'coral':''}">${b.status==='cancelled'?'×':'✓'}</span><div class="activity-text"><b>${escapeHtml(warehouse(b.warehouseId)?.name||'Warehouse')}</b> · ${escapeHtml(shift(b.shiftId)?.name||'')}<small>${escapeHtml(formatDate(b.date,{day:'numeric',month:'short',year:'numeric'}))} · ${labelStatus(b.status)}${b.lateCancel?' · Late cancellation':''}</small></div></div>`).join(''):'<div class="empty-inset">No shift history recorded.</div>';openModal(escapeHtml(w?.name||'Worker profile'),`${escapeHtml(w?.workerId||'')} · ${escapeHtml(a?.name||'No agency')}`,`${ban}<div class="detail-list"><div class="detail-block"><small>Phone</small><b>${escapeHtml(w?.phone||'Not provided')}</b></div><div class="detail-block"><small>Access</small><b>${w?.banned?'Blocked':'Active'}</b></div><div class="detail-block"><small>Joined</small><b>${w?.joined?escapeHtml(formatDate(w.joined,{day:'numeric',month:'short',year:'numeric'})):'—'}</b></div><div class="detail-block"><small>Late cancellations</small><b>${late.length}</b></div></div>${auditRows?`<div style="margin-top:17px"><div class="panel-title" style="font-size:12px">Access history</div><div style="margin-top:8px">${auditRows}</div></div>`:''}<div style="margin-top:17px"><div class="panel-title" style="font-size:12px">Recent shift activity</div><div style="margin-top:8px">${historyRows}</div></div>`,modalFoot('Close',w?.banned?'Unblock worker':'Block worker','toggle-ban-modal'));$('#modalRoot').querySelector('[data-action="toggle-ban-modal"]').dataset.id=workerId;};
  const shiftStartDate = b => {const s=shift(b.shiftId),[h,m]=String(s?.start||'07:30').split(':').map(Number);const d=new Date(`${b.date}T00:00:00`);d.setHours(h,m,0,0);return d;};
  const openCancel = (id) => {const b=booking(id),w=worker(b?.workerRef);if(!b)return;const mins=(shiftStartDate(b)-new Date())/60000,late=mins<=Number(db.settings.cancelWindow);openModal(late?'Review a late cancellation':'Cancel this shift',late?`This shift starts in ${Math.max(0,Math.floor(mins))} minutes. An agency PIC must review the reason.`:'The worker’s booking will be released back to the agency quota.',`<div class="detail-list"><div class="detail-block"><small>Worker</small><b>${escapeHtml(w?.name||'')}</b></div><div class="detail-block"><small>Shift</small><b>${escapeHtml(shift(b.shiftId)?.name||'')} · ${escapeHtml(formatDate(b.date))}</b></div></div><form id="cancelForm" data-id="${id}" data-late="${late}"><div class="field" style="margin-top:14px"><label for="cancelReason">${late?'Reason for late cancellation':'Reason (optional)'}</label><textarea id="cancelReason" name="reason" ${late&&db.settings.requireReason?'required':''} maxlength="500" placeholder="Add the worker’s reason for cancelling"></textarea></div></form>${late?'<div class="policy-note"><span class="policy-icon">ⓘ</span><span>A PIC reviews this reason. The worker will only be blocked if the reason is not accepted or cancellations are repeated.</span></div>':''}`,modalFoot('Keep booking',late?'Submit for PIC review':'Confirm cancellation','submit-cancel'));};
  const pageNav = page => {view=page;bookingPage=1;workerPage=1;$('#sidebar').classList.remove('open');renderApp();};
  const switchPortal = () => {view='worker-portal';selectedWarehouse='all';renderApp();};
  const refreshPortalAvailability = async () => {const form=$('#workerSignupForm');if(!form)return;const date=$('#signupDate')?.value||isoToday(),wh=$('#signupWarehouse')?.value||'';let s=$('#signupShift')?.value||'day';const site=warehouse(wh);if(site?.shifts?.length&&!site.shifts.includes(s)){s=site.shifts[0];$('#signupShift').value=s;}const list=$('#signupAvailability');if(!list)return;if(isPublicSignup){try{const url=`/api/public/availability?date=${encodeURIComponent(date)}&warehouseId=${encodeURIComponent(wh)}&shiftId=${encodeURIComponent(s)}`;const response=await fetch(url,{cache:'no-store'}),data=await response.json();if(!response.ok)throw new Error(data.error||'Availability could not be checked.');list.innerHTML=data.agencies.map(a=>`<div class="availability-item"><span><b>${escapeHtml(a.name)}</b><small>${a.status==='Open'?'Applications open for this agency':'Agency quota has been reached'}</small></span><span class="${a.status==='Open'?'open-indicator':'full-indicator'}">${a.status}</span></div>`).join('')||'<div class="empty-inset">No agencies are accepting sign-ups.</div>';}catch(error){list.innerHTML=`<div class="empty-inset">${escapeHtml(error.message||'Availability could not be checked.')}</div>`;}return;}list.innerHTML=getAvailabilityMarkup(date,wh,s);};
  const updateChoiceCards = root => {$$('[data-choice-card]',root).forEach(card=>{const input=$('input',card);card.classList.toggle('selected',!!input?.checked);});};
  const submitSignup = async form => {const values=Object.fromEntries(new FormData(form));if(isPublicSignup){const response=await fetch('/api/public/signup',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(values)}),data=await response.json();if(!response.ok)throw new Error(data.error||'Shift request could not be saved.');form.reset();$('#workerIdField')?.classList.remove('hidden');$('#signupWorkerId').required=true;updateChoiceCards(form);await refreshPortalAvailability();openModal('Request sent to your agency PIC',`Booking reference ${escapeHtml(data.bookingId)} · ${escapeHtml(data.status)}`,`<div class="worker-summary"><span><b>Your Shiftmate worker ID</b><small>Keep this ID for your next shift request.</small></span><code>${escapeHtml(data.workerId)}</code></div><p class="demo-note" style="text-align:left">Your agency PIC will review the request and confirm your shift. You can share the booking reference with them on WhatsApp.</p>`,modalFoot('Close'));return;}const type=values.workerType;if(type==='existing'&&!values.workerId?.trim())throw new Error('Enter your warehouse worker ID.');if(!agency(values.agencyId)?.active)throw new Error('This agency is not accepting shift requests.');let w;if(type==='existing'){w=db.workers.find(row=>row.workerId.toLowerCase()===values.workerId.trim().toLowerCase());if(w?.banned)throw new Error('This worker ID is blocked. Contact your agency PIC.');if(w&&w.agencyId!==values.agencyId)throw new Error('That worker ID belongs to a different agency. Ask the PIC to update the record.');if(!w){w={id:`w-${Date.now()}`,name:values.name.trim(),workerId:values.workerId.trim(),agencyId:values.agencyId,phone:values.phone.trim(),isNew:false,banned:false,joined:isoToday()};db.workers.push(w);}else{w.name=values.name.trim();w.phone=values.phone.trim();}}else{w={id:`w-${Date.now()}`,name:values.name.trim(),workerId:makeWorkerId(),agencyId:values.agencyId,phone:values.phone.trim(),isNew:true,banned:false,joined:isoToday()};db.workers.push(w);}assertNoDuplicateShift(w.id,values.date,values.shiftId);if(availableFor(values.date,values.warehouseId,values.shiftId,values.agencyId)<=0)throw new Error('This agency is full for that shift. Choose another agency, warehouse or time.');const b={id:makeBookingId(),workerRef:w.id,agencyId:values.agencyId,warehouseId:values.warehouseId,shiftId:values.shiftId,date:values.date,status:'pending',createdAt:Date.now(),lateCancel:false,attendance:'unmarked'};db.bookings.unshift(b);logActivity(`${w.name} requested ${shift(b.shiftId)?.name} at ${warehouse(b.warehouseId)?.name}`,'booked');save();toast(`Shift request sent · worker ID ${w.workerId}`);view='overview';renderApp();};
  const cancelBooking = form => {const b=booking(form.dataset.id);if(!b||b.status==='cancelled')throw new Error('This booking was already cancelled.');const reason=$('[name="reason"]',form).value.trim(),late=form.dataset.late==='true';if(late&&db.settings.requireReason&&reason.length<8)throw new Error('Add a clear reason of at least 8 characters for the PIC to review.');b.status='cancelled';b.lateCancel=late;b.cancelReason=reason;b.cancelledAt=Date.now();const w=worker(b.workerRef);logActivity(`${w?.name||'Worker'} cancelled ${warehouse(b.warehouseId)?.name} · ${shift(b.shiftId)?.name}${late?' · PIC review needed':''}`,late?'cancel':'booked');save();closeModal();renderApp();toast(late?'Cancellation sent for PIC review.':'Booking cancelled and quota released.');};
  const download = (filename,content,type='text/plain') => {const blob=new Blob([content],{type});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);};
  const csvEscape = value => `"${String(value??'').replaceAll('"','""')}"`;
  const exportBookings = () => {const rows=[['Booking ID','Worker','Worker ID','Agency','Warehouse','Shift','Date','Status'],...db.bookings.map(b=>[b.id,worker(b.workerRef)?.name,worker(b.workerRef)?.workerId,agency(b.agencyId)?.name,warehouse(b.warehouseId)?.name,shift(b.shiftId)?.name,b.date,labelStatus(b.status)])];download(`shiftmate-bookings-${isoToday()}.csv`,rows.map(r=>r.map(csvEscape).join(',')).join('\n'),'text/csv');toast('Bookings exported.');};
  const exportWorkers = () => {const rows=[['Name','Worker ID','Agency','Phone','Access','Joined'],...db.workers.map(w=>[w.name,w.workerId,agency(w.agencyId)?.name,w.phone,w.banned?'Blocked':'Active',w.joined])];download(`shiftmate-workers-${isoToday()}.csv`,rows.map(r=>r.map(csvEscape).join(',')).join('\n'),'text/csv');toast('Worker directory exported.');};
  const clickAction = async (action,el) => {
    const id=el.dataset.id;
    switch(action){
      case 'new-booking':openNewBooking();break;
      case 'worker-portal':switchPortal();break;
      case 'new-worker':openNewWorker();break;
      case 'new-agency':openNewAgency();break;
      case 'new-warehouse':openNewWarehouse();break;
      case 'edit-quota':openQuotaModal(id);break;
      case 'view-worker':openWorkerDetail(id);break;
      case 'view-booking':{const b=booking(id);if(!b)break;const w=worker(b.workerRef),a=agency(b.agencyId),wh=warehouse(b.warehouseId),s=shift(b.shiftId);openModal(`Booking ${escapeHtml(b.id)}`,`${escapeHtml(formatDate(b.date,{weekday:'long',day:'numeric',month:'long',year:'numeric'}))}`,`<div class="detail-list"><div class="detail-block"><small>Worker</small><b>${escapeHtml(w?.name||'Unknown')} · ${escapeHtml(w?.workerId||'')}</b></div><div class="detail-block"><small>Agency</small><b>${escapeHtml(a?.name||'—')}</b></div><div class="detail-block"><small>Warehouse</small><b>${escapeHtml(wh?.name||'—')}</b></div><div class="detail-block"><small>Shift</small><b>${escapeHtml(s?.name||'—')} · ${escapeHtml(s?.time||'')}</b></div><div class="detail-block"><small>Status</small><b>${labelStatus(b.status)}${b.lateCancel?' · PIC review':''}</b></div><div class="detail-block"><small>Created</small><b>${new Intl.DateTimeFormat('en-MY',{hour:'numeric',minute:'2-digit'}).format(new Date(b.createdAt))}</b></div></div>${b.cancelReason?`<div class="policy-note" style="margin-top:14px"><span>ⓘ</span><span>Cancellation reason: ${escapeHtml(b.cancelReason)}</span></div>`:''}`,modalFoot('Close'));break;}
      case 'confirm-booking':{const b=booking(id);if(b&&b.status==='pending'){b.status='confirmed';b.confirmedAt=Date.now();logActivity(`${worker(b.workerRef)?.name||'Worker'} booking ${b.id} confirmed`,'booked');save();renderApp();toast(`Booking ${b.id} confirmed.`);}break;}
      case 'attendance-status':{const b=booking(id);if(!b||!['confirmed','completed'].includes(b.status))break;b.attendance=el.dataset.status;b.attendanceAt=Date.now();if(b.attendance==='no-show')logActivity(`${worker(b.workerRef)?.name||'Worker'} recorded as a no-show · PIC follow-up needed`,'cancel');else logActivity(`${worker(b.workerRef)?.name||'Worker'} marked present`,'booked');save();renderApp();toast(b.attendance==='present'?'Attendance marked present.':'No-show recorded for agency follow-up.');break;}
      case 'review-approve':{const b=booking(id);if(b){b.reviewStatus='approved';b.reviewedAt=Date.now();b.reviewedBy='Agency PIC';logActivity(`${worker(b.workerRef)?.name||'Worker'} cancellation reason accepted by PIC`,'booked');save();renderApp();toast('Cancellation reason accepted.');}break;}
      case 'review-reject':{const b=booking(id),w=worker(b?.workerRef);if(b&&w){b.reviewStatus='rejected';b.reviewedAt=Date.now();b.reviewedBy='Agency PIC';w.banned=true;w.banReason=`Late cancellation reason rejected: ${b.cancelReason||'No reason supplied'}`;w.banHistory=w.banHistory||[];w.banHistory.push({action:'blocked',reason:w.banReason,time:Date.now(),by:'Agency PIC'});logActivity(`${w.name} blocked after PIC rejected a late cancellation reason`,'cancel');save();renderApp();toast(`${w.name} blocked from new shift bookings.`);}break;}
      case 'export-attendance':case 'export-report':{const rows=[['Date','Booking ID','Worker','Worker ID','Agency','Warehouse','Shift','Booking status','Attendance','Cancellation reason'],...db.bookings.filter(b=>b.date===selectedDate).map(b=>[b.date,b.id,worker(b.workerRef)?.name,worker(b.workerRef)?.workerId,agency(b.agencyId)?.name,warehouse(b.warehouseId)?.name,shift(b.shiftId)?.name,labelStatus(b.status),b.attendance||'unmarked',b.cancelReason||''])];download(`shiftmate-${action==='export-report'?'report':'attendance'}-${selectedDate}.csv`,rows.map(r=>r.map(csvEscape).join(',')).join('\n'),'text/csv');toast('Report downloaded.');break;}
      case 'cancel-booking':openCancel(id);break;
      case 'toggle-ban':toggleBan(id);break;
      case 'toggle-ban-modal':toggleBan(id,true);break;
      case 'toggle-agency':{const a=agency(id);if(a){a.active=!a.active;logActivity(`${a.name} was ${a.active?'activated':'paused'}`,'quota');save();renderApp();toast(`${a.name} ${a.active?'activated':'paused'}.`);}break;}
      case 'agency-message':{const a=agency(id),wh=db.warehouses.find(w=>w.active),s=SHIFT_RULES[0],msg=`SHIFT AVAILABILITY · ${wh?.name||'Warehouse'}\n${formatDate(selectedDate,{weekday:'long',day:'numeric',month:'long'})} · ${s.name} (${s.time})\nAgency: ${a?.name||'Agency'}\nStatus: ${availableFor(selectedDate,wh?.id||'',s.id,id)>0?'OPEN FOR SIGN-UP':'FULL — no further requests'}\n\nRegister through Shiftmate: ${location.origin}/signup\nWait for your agency PIC to confirm.`;try{await navigator.clipboard.writeText(msg);toast('WhatsApp update copied. Paste it into the agency group.');}catch{toast(msg,'success');}break;}
      case 'copy-whatsapp':{const msg=decodeURIComponent(el.dataset.message||'');try{await navigator.clipboard.writeText(msg);toast('Message copied. Paste it into WhatsApp.');}catch{openModal('Copy message','Select and copy this update into WhatsApp.',`<textarea readonly style="width:100%;min-height:145px;border:1px solid var(--line);border-radius:8px;padding:10px">${escapeHtml(msg)}</textarea>`,modalFoot('Close'));}break;}
      case 'refresh-update':{const d=$('#updateDate')?.value||selectedDate,wh=$('#updateWarehouse')?.value||'',s=$('#updateShift')?.value||'day',a=$('#updateAgency')?.value||'';$('#whatsappMessage').innerHTML=whatsappPreview(d,wh,s,a);break;}
      case 'admin-view':view='overview';renderApp();break;
      case 'export-bookings':exportBookings();break;
      case 'export-workers':exportWorkers();break;
      case 'export-data':download(`shiftmate-data-${isoToday()}.json`,JSON.stringify(db,null,2),'application/json');toast('Workspace data downloaded.');break;
      case 'toggle-setting':{const key=el.dataset.setting;db.settings[key]=!db.settings[key];save();renderApp();break;}
      case 'save-settings':{const val=Number($('#cancelWindow').value);if(!Number.isFinite(val)||val<15||val>720){toast('Choose a review window between 15 and 720 minutes.','error');break;}db.settings.cancelWindow=val;save();renderApp();toast('Cancellation policy saved.');break;}
      case 'reset-data':openModal('Reset sample data?','This replaces the current browser demo records with the original sample workspace.','<p style="font-size:11px;color:#758195;line-height:1.55">Your current worker, agency, quota and booking changes in this browser will be removed.</p>',modalFoot('Keep my data','Reset demo','confirm-reset'));break;
      case 'confirm-reset':db=defaultData();selectedDate=isoToday();selectedWarehouse='all';bookingSearch='';workerSearch='';save();closeModal();view='overview';renderApp();toast('Sample workspace restored.');break;
      case 'submit-admin-booking':{const f=$('#adminBookingForm');if(!f.reportValidity())break;try{const b=addBooking(Object.fromEntries(new FormData(f)));closeModal();renderApp();toast(`Booking ${b.id} created.`);}catch(e){toast(e.message,'error');}break;}
      case 'submit-new-worker':{const f=$('#newWorkerForm');if(!f.reportValidity())break;const v=Object.fromEntries(new FormData(f));const wid=v.workerId.trim()||makeWorkerId();if(db.workers.some(w=>w.workerId.toLowerCase()===wid.toLowerCase())){toast('That worker ID is already in use.','error');break;}db.workers.push({id:`w-${Date.now()}`,name:v.name.trim(),workerId:wid,agencyId:v.agencyId,phone:v.phone.trim(),isNew:!v.workerId.trim(),banned:false,joined:isoToday()});logActivity(`${v.name.trim()} was added to the worker directory`,'booked');save();closeModal();renderApp();toast(`Worker added · ${wid}`);break;}
      case 'submit-new-agency':{const f=$('#newAgencyForm');if(!f.reportValidity())break;const v=Object.fromEntries(new FormData(f));const a={id:`agency-${Date.now()}`,name:v.name.trim(),pic:v.pic.trim(),phone:v.phone.trim(),defaultQuota:Number(v.defaultQuota),tone:v.tone,active:true};db.agencies.push(a);save();closeModal();renderApp();toast(`${a.name} added.`);break;}
      case 'submit-new-warehouse':{const f=$('#newWarehouseForm');if(!f.reportValidity())break;const v=Object.fromEntries(new FormData(f));const shifts=[...f.querySelectorAll('[name="shifts"]:checked')].map(i=>i.value);if(!shifts.length){toast('Choose at least one shift.','error');break;}const w={id:`warehouse-${Date.now()}`,name:v.name.trim(),city:v.city.trim(),code:v.code.trim().toUpperCase(),tone:'teal-cover',active:true,shifts};db.warehouses.push(w);save();closeModal();renderApp();toast(`${w.name} added.`);break;}
      case 'submit-quota':{const f=$('#quotaForm');if(!f.reportValidity())break;const v=Object.fromEntries(new FormData(f)),aId=f.dataset.agency;for(const sid of ['day','night']){const val=Number(v[sid]);const booked=activeBookings(v.date,v.warehouseId,sid,aId);if(val<booked){toast(`Quota cannot be lower than the ${booked} active ${sid} bookings.`,'error');return;}db.quotas[quotaKey(v.date,v.warehouseId,sid,aId)]=val;}logActivity(`${agency(aId)?.name||'Agency'} updated a shift quota`,'quota');save();closeModal();renderApp();toast('Agency quotas updated.');break;}
      case 'submit-cancel':{const f=$('#cancelForm');if(!f.reportValidity())break;try{cancelBooking(f);}catch(e){toast(e.message,'error');}break;}
      case 'submit-modal':closeModal();break;
      case 'close-modal':closeModal();break;
      case 'workspace':openModal('Northstar Logistics','Operations workspace',`<div class="detail-list"><div class="detail-block"><small>Workspace</small><b>Northstar Logistics</b></div><div class="detail-block"><small>Type</small><b>Warehouse operations</b></div></div><p style="font-size:11px;color:#7f8a9a;line-height:1.55;margin:14px 0 0">This demo has one workspace. Manage multiple warehouses and agency partners from the navigation menu.</p>`,modalFoot('Close'));break;
      case 'profile':openModal('Nur Badariah','Workspace administrator',`<div class="detail-list"><div class="detail-block"><small>Role</small><b>Workspace admin</b></div><div class="detail-block"><small>Workspace</small><b>Northstar Logistics</b></div></div><p class="demo-note">Profile and sign-in settings are managed by the account owner.</p>`,modalFoot('Close'));break;
      case 'help':openModal('Quick guide','The basics of Shiftmate.',`<div class="quick-guide"><div class="guide-step"><span class="guide-num">1</span><div><b>Set capacity by agency</b><p>In Agencies, choose Set quota and enter worker limits for each site and shift.</p></div></div><div class="guide-step"><span class="guide-num">2</span><div><b>Share the worker sign-up</b><p>Open the worker portal from the overview and submit a sample shift request.</p></div></div><div class="guide-step"><span class="guide-num">3</span><div><b>Review changes</b><p>Approve or cancel bookings, and review a worker’s history before changing access.</p></div></div><div class="guide-step"><span class="guide-num">4</span><div><b>Share availability</b><p>Copy a WhatsApp update with open or full status. Quota counts stay private to coordinators.</p></div></div></div>`,modalFoot('Got it'));break;
      case 'notifications':{const pending=db.bookings.filter(b=>b.status==='pending').length,late=pendingReviews().length,noShows=db.bookings.filter(b=>b.attendance==='no-show').length;openModal('Notifications',`${pending+late+noShows} items need attention.`,pending||late||noShows?`<div class="activity-list">${pending?`<button class="activity-item notification-link" data-action="close-modal" data-nav="bookings"><span class="activity-icon blue">◷</span><span class="activity-text"><b>${pending} shift request${pending===1?'':'s'} pending</b><small>Open bookings to confirm them.</small></span></button>`:''}${late?`<button class="activity-item notification-link" data-action="close-modal" data-nav="reviews"><span class="activity-icon coral">!</span><span class="activity-text"><b>${late} late cancellation${late===1?'':'s'} to review</b><small>Open PIC review queue.</small></span></button>`:''}${noShows?`<button class="activity-item notification-link" data-action="close-modal" data-nav="attendance"><span class="activity-icon coral">!</span><span class="activity-text"><b>${noShows} no-show${noShows===1?'':'s'} recorded</b><small>Open attendance register.</small></span></button>`:''}</div>`:'<div class="empty-inset">You’re all caught up.</div>',modalFoot('Close'));break;}
    }
  };
  function toggleBan(id,fromModal=false){const w=worker(id);if(!w)return;if(w.banned){w.banned=false;w.banHistory=w.banHistory||[];w.banHistory.push({action:'unblocked',reason:'Access restored by agency PIC',time:Date.now(),by:'Agency PIC'});w.banReason='';logActivity(`${w.name} was unblocked by an agency PIC`,'booked');save();if(fromModal){closeModal();renderApp();}else renderApp();toast(`${w.name} is unblocked.`);}else{openModal(`Block ${escapeHtml(w.name)}?`,'An agency PIC can restore access at any time.',`<form id="banForm" data-id="${id}"><div class="field"><label>Reason for block</label><textarea name="reason" required minlength="8" maxlength="500" placeholder="Explain why this worker should not book new shifts"></textarea></div></form>`,modalFoot('Cancel','Block worker','confirm-ban'));}}
  $('#pageContent').addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){pageNav(nav.dataset.nav);return;}const actionEl=e.target.closest('[data-action]');if(actionEl){clickAction(actionEl.dataset.action,actionEl);return;}const bf=e.target.closest('[data-book-filter]');if(bf){bookingFilter=bf.dataset.bookFilter;bookingPage=1;renderApp();return;}const wf=e.target.closest('[data-worker-filter]');if(wf){workerFilter=wf.dataset.workerFilter;workerPage=1;renderApp();return;}});
  $('#sidebar').addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();pageNav(nav.dataset.nav);return;}const actionEl=e.target.closest('[data-action]');if(actionEl){clickAction(actionEl.dataset.action,actionEl);}});
  $('#pageContent').addEventListener('input',e=>{if(e.target.id==='bookingSearch'){bookingSearch=e.target.value;bookingPage=1;const start=e.target.selectionStart;renderApp();const field=$('#bookingSearch');field?.focus();field?.setSelectionRange(start,start);}if(e.target.id==='workerSearch'){workerSearch=e.target.value;workerPage=1;const start=e.target.selectionStart;renderApp();const field=$('#workerSearch');field?.focus();field?.setSelectionRange(start,start);}});
  $('#pageContent').addEventListener('change',e=>{
    if(e.target.id==='overviewDate'){selectedDate=e.target.value;renderApp();}
    if(e.target.id==='overviewWarehouse'){selectedWarehouse=e.target.value;renderApp();}
    if(e.target.id==='agencyDate'||e.target.id==='warehouseDate'){selectedDate=e.target.value;renderApp();}
    if(['scheduleDate','attendanceDate','reportDate'].includes(e.target.id)){selectedDate=e.target.value;renderApp();}
    if(e.target.id==='bookingDateFilter'||e.target.id==='bookingWarehouseFilter'){const date=$('#bookingDateFilter')?.value,wh=$('#bookingWarehouseFilter')?.value;$$('#bookingTableBody tr').forEach(row=>{const bId=row.querySelector('[data-id]')?.dataset.id;const b=booking(bId);row.hidden=!!((date&&date!=='all'&&b?.date!==date)||(wh&&wh!=='all'&&b?.warehouseId!==wh));});}
    if(['signupDate','signupWarehouse','signupShift'].includes(e.target.id))refreshPortalAvailability();
    if(e.target.name==='workerType'){const isExisting=e.target.value==='existing';$('#workerIdField')?.classList.toggle('hidden',!isExisting);const input=$('#signupWorkerId');if(input){input.required=isExisting;if(!isExisting)input.value='';}updateChoiceCards($('#workerSignupForm'));}
    if(e.target.matches('[data-choice-card] input'))updateChoiceCards($('#modalRoot'));
    if(['updateDate','updateWarehouse','updateShift','updateAgency'].includes(e.target.id)){$('#whatsappMessage').innerHTML=whatsappPreview($('#updateDate').value,$('#updateWarehouse').value,$('#updateShift').value,$('#updateAgency').value);}
  });
  $('#pageContent').addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='workerSignupForm'){if(!e.target.reportValidity())return;try{await submitSignup(e.target);}catch(err){toast(err.message,'error');}}});
  $('#modalRoot').addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){const destination=nav.dataset.nav;closeModal();pageNav(destination);return;}const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action;if(['submit-admin-booking','submit-new-worker','submit-new-agency','submit-new-warehouse','submit-quota','submit-cancel','submit-modal','close-modal','confirm-reset','toggle-ban-modal'].includes(action)){clickAction(action,a);return;}if(action==='confirm-ban'){const f=$('#banForm');if(!f.reportValidity())return;const w=worker(f.dataset.id);if(w){w.banned=true;w.banReason=$('[name="reason"]',f).value.trim();w.banHistory=w.banHistory||[];w.banHistory.push({action:'blocked',reason:w.banReason,time:Date.now(),by:'Agency PIC'});logActivity(`${w.name} was blocked after PIC review`,'cancel');save();closeModal();renderApp();toast(`${w.name} blocked from new sign-ups.`);}return;}});
  $('#modalRoot').addEventListener('change',e=>{if(e.target.matches('[data-choice-card] input'))updateChoiceCards($('#modalRoot'));});
  $('#modalRoot').addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
  $('#pageContent').addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){if(page.dataset.action==='page-bookings')bookingPage=Number(page.dataset.page);if(page.dataset.action==='page-workers')workerPage=Number(page.dataset.page);renderApp();}});
  document.addEventListener('click',e=>{if(e.target.closest('#menuButton'))$('#sidebar').classList.toggle('open');else if(window.innerWidth<780&&!e.target.closest('#sidebar'))$('#sidebar').classList.remove('open');const actionEl=e.target.closest('[data-action]');if(actionEl&&!$('#pageContent').contains(actionEl)&&!$('#modalRoot').contains(actionEl)&&!$('#sidebar').contains(actionEl))clickAction(actionEl.dataset.action,actionEl);});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
  $('#todayLabel').textContent=new Intl.DateTimeFormat('en-MY',{weekday:'short',day:'numeric',month:'short'}).format(new Date());
  const loadPublicWorkspace = async () => {try{const response=await fetch('/api/public/config',{cache:'no-store'}),config=await response.json();if(!response.ok)throw new Error(config.error||'Shiftmate sign-up is not ready yet.');db={agencies:config.agencies,warehouses:config.warehouses,workers:[],bookings:[],quotas:{},settings:{cancelWindow:config.settings.cancelWindow,requireReason:true,whatsappAlerts:false},activity:[]};renderApp();await refreshPortalAvailability();}catch(error){renderApp();const list=$('#signupAvailability');if(list)list.innerHTML=`<div class="empty-inset">${escapeHtml(error.message||'Shiftmate is not ready yet. Contact your agency PIC.')}</div>`;const submit=$('#workerSignupForm button[type=submit]');if(submit)submit.disabled=true;}};
  const loadSharedAdmin = async () => {try{let response=await fetch('/api/state',{cache:'no-store'});if(!response.ok)throw new Error((await response.json()).error||'Admin access could not be verified.');let current=await response.json();if(current?.state){db=current.state;remoteRevision=current.revision;localStorage.setItem(KEY,JSON.stringify(db));sharedReady=true;renderApp();return;}response=await fetch('/api/state',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({revision:null,state:db})});if(response.status===201){current=await response.json();db=current.state;remoteRevision=current.revision;sharedReady=true;localStorage.setItem(KEY,JSON.stringify(db));renderApp();toast('Shared Shiftmate workspace is ready.');return;}if(response.status===409){current=await (await fetch('/api/state',{cache:'no-store'})).json();if(current?.state){db=current.state;remoteRevision=current.revision;sharedReady=true;localStorage.setItem(KEY,JSON.stringify(db));renderApp();return;}}throw new Error((await response.json().catch(()=>({}))).error||'Shared storage setup could not be completed.');}catch(error){sharedReady=false;toast(error.message||'Shared storage is unavailable.','error');}};
  renderApp();
  if(isPublicSignup) void loadPublicWorkspace(); else void loadSharedAdmin();
})();
